def getv(ctx, path, default=''):
    if isinstance(ctx, dict) and path in ctx:
        return ctx.get(path, default)
    cur = ctx
    for part in path.split('.'):
        if isinstance(cur, dict) and part in cur:
            cur = cur.get(part)
        else:
            return default
    return cur

def txt(x):
    if x is None:
        return ''
    if isinstance(x, list):
        return ' '.join([txt(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([txt(k) + ' ' + txt(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    return ''

def hasinv(inv, target):
    s = txt(inv)
    return bool(target and target in s and 'not carrying anything' not in s and 'nothing' not in s and '[]' not in s)

def hasact(adm, prefix, target, dest, picktwo, placed):
    for a in adm or []:
        al = txt(a)
        if prefix and not al.startswith(prefix):
            continue
        if target and target not in al:
            continue
        if dest and dest not in al:
            continue
        if picktwo and ' pick_two ' in txt(getv(ctx, 'task.task_type', '')) and (placed or target in al and 'take ' in al and ' from ' in al):
            continue
        return True
    return False

def hook(ctx, nb):
    task = getv(ctx, 'task', {})
    world = getv(ctx, 'world', {})
    tt = txt(task.get('task_type') or getv(ctx, 'task.task_type', ''))
    target = txt(task.get('target_type') or getv(ctx, 'task.target_type', ''))
    dest = txt(task.get('destination_type') or getv(ctx, 'task.destination_type', ''))
    adm = ctx.get('admissible') or []
    act = txt(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    obs = txt(ctx.get('observation', ''))
    inv = world.get('inventory') if isinstance(world, dict) else None
    if not inv:
        inv = getv(ctx, 'world.inventory', '')
    verb = needverb(tt)
    req = ('clean' in tt) or ('heat' in tt) or ('cool' in tt)
    placed = world.get('placed_count') if isinstance(world, dict) else getv(ctx, 'world.placed_count', 0)
    if not isinstance(placed, int):
        placed = 0
    if verb and target and target in act and act.startswith(verb + ' ') and 'nothing happens' not in obs and 'cannot' not in obs:
        nb['transform_done'] = True
    old = nb.get('placed_count', 0)
    if not isinstance(old, int):
        old = 0
    if verb and target and target in act and act.startswith('put ') and 'you put' in obs and not (req and verb in act and not nb.get('transform_done')):
        if placed < old + 1:
            placed = old + 1
    nb['placed_count'] = placed
    carrying = hasinv(inv, target)
    wrong = bool(inv and txt(inv) and 'not carrying anything' not in txt(inv) and 'nothing' not in txt(inv) and '[]' not in txt(inv) and not carrying)
    targettake = hasact(adm, 'take ', target, '', False, placed > 0)
    destput = hasact(adm, 'put ', target, dest, False, False)
    if req and verb and target and target in act and act.startswith(verb + ' ') and 'nothing happens' not in obs and 'cannot' not in obs:
        nb['transform_done'] = True
    if req and verb and target and target in act and act.startswith('put ') and verb in act and 'nothing happens' not in obs and 'cannot' not in obs:
        nb['transform_done'] = True
    if req and verb and target and target in act and act.startswith('put ') and verb in act and 'you put' in obs and not nb.get('transform_done'):
        nb['transform_done'] = True
    if 'pick_two' in tt and 'you put' in obs and target and target in act and act.startswith('put '):
        if placed < old + 1:
            placed = old + 1
    nb['placed_count'] = placed
    if wrong:
        stage = 'wrong_inventory'
    elif carrying:
        if req and verb and target and target in act and act.startswith(verb + ' ') and 'nothing happens' not in obs and 'cannot' not in obs:
            stage = 'transform'
        elif req and verb and target and target in act and act.startswith('put ') and verb in act and not nb.get('transform_done'):
            stage = 'transform'
        elif nb.get('transform_done') or not req:
            stage = 'put_target' if destput else 'go_destination'
    else:
        if 'pick_two' in tt and placed > 0 and not carrying:
            stage = 'find_target'
        elif targettake:
            stage = 'take_target'
        else:
            stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['required_verb'] = verb
    nb['required_transform'] = req
    nb['carrying_target'] = carrying
    nb['wrong_inventory'] = wrong
    return None

