def txt(x):
    if x is None:
        return ''
    if isinstance(x, list):
        return ' '.join([txt(i) for i in x])
    return str(x).lower()

def hook(ctx, nb):
    stage = nb.get('stage')
    target = nb.get('target_type') or txt(getv(ctx, 'task.target_type', 'target'))
    dest = nb.get('destination_type') or txt(getv(ctx, 'task.destination_type', 'destination'))
    verb = nb.get('required_verb') or ''
    tt = nb.get('task_type') or txt(getv(ctx, 'task.task_type', ''))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target object. Do not treat it as the goal; put it down only to recover the requested ' + target + '.'
    elif stage == 'take_target' and target:
        msg = 'A requested ' + target + ' is available here; take it instead of continuing to search.'
    elif stage == 'transform' and verb and target and dest:
        if verb in ('clean', 'heat', 'cool') and dest in ('sinkbasin', 'microwave', 'fridge'):
            msg = 'Carry the ' + target + ' to the ' + dest + ' and use the ' + verb + ' action before placing it.'
        else:
            msg = 'Carry the ' + target + ' and use the required ' + verb + ' action before any put action.'
    elif stage == 'put_target' and verb and target and verb not in ('clean', 'heat', 'cool'):
        if verb == 'cool':
            msg = 'Carry the ' + target + ' to the ' + dest + ' and put it there; do not cool it again.'
        else:
            msg = 'Carry the ' + target + ' to the ' + dest + ' and put it there; do not transform it again.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the ' + target + ' to the ' + dest + ' and put it there when the put action appears.'
    elif 'pick_two' in tt and nb.get('placed_count', 0) > 0 and target and not nb.get('carrying_target'):
        msg = 'One ' + target + ' is already placed; leave it there, find another ' + target + ', and use the same ' + dest + ' destination.'
    if not msg or msg == nb.get('last_hint'):
        return None
    nb['last_hint'] = msg
    return {'message': msg}
